package com.fitmind.controller; import com.fitmind.common.*; import com.fitmind.dto.MealRecordRequest; import com.fitmind.entity.MealRecord; import com.fitmind.service.*; import com.fitmind.vo.ImageAnalysisVO; import com.fitmind.vo.NutritionStatisticsVO; import lombok.RequiredArgsConstructor; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import javax.validation.Valid; import java.time.LocalDate;
@RestController @RequestMapping("/api/meals") @RequiredArgsConstructor public class MealController { private final MealService service; private final ImageAnalysisService imageService; @GetMapping public Result<PageResult<MealRecord>> page(@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate date,@RequestParam(defaultValue="1") long page,@RequestParam(defaultValue="10") long size){return Result.ok(service.page(date,page,size));} @PostMapping public Result<MealRecord> create(@Valid @RequestBody MealRecordRequest r){return Result.ok(service.create(r));} @PutMapping("/{id}") public Result<MealRecord> update(@PathVariable long id,@Valid @RequestBody MealRecordRequest r){return Result.ok(service.update(id,r));} @DeleteMapping("/{id}") public Result<Void> delete(@PathVariable long id){service.delete(id);return Result.ok();} @GetMapping("/nutrition") public Result<NutritionStatisticsVO> nutrition(@RequestParam(defaultValue="7") int days){return Result.ok(service.nutrition(days));} @PostMapping("/analyze-image") public Result<ImageAnalysisVO> image(@RequestParam("file") MultipartFile file){return Result.ok(imageService.analyze(file));} }
